// n8n Code node (JavaScript)

// items 是 Google Sheets 节点传入的所有行
const structured = {};
let promptText = '';

// 防御性判断
if (!items || items.length === 0) {
  return [
    {
      json: {
        error: 'No data received from Google Sheets'
      }
    }
  ];
}

// 工具函数：兼容不同字段命名
function getField(obj, possibleKeys) {
  for (const key of possibleKeys) {
    if (obj[key] !== undefined && obj[key] !== null && obj[key] !== '') {
      return obj[key];
    }
  }
  return null;
}

for (const item of items) {
  const row = item.json;

  const section = getField(row, ['section', 'Section', 'SECTION']);
  const key = getField(row, ['key', 'Key', 'KEY']);
  const content = getField(row, ['content', 'Content', 'CONTENT']);

  // 如果这一行字段不完整，直接跳过
  if (!section || !key || !content) {
    continue;
  }

  if (!structured[section]) {
    structured[section] = {};
    promptText += `\n【${section}】\n`;
  }

  structured[section][key] = content;
  promptText += `- ${key}: ${content}\n`;
}

return [
  {
    json: {
      structured_context: structured,
      prompt_context: promptText.trim()
    }
  }
];

// After Merge node, all incoming items are in `items`
// Each item represents one agent output (Agent4, Agent5)

let finalText = '';

items.forEach((item, index) => {
  // Safely extract text from common LLM output fields
  const text =
    item.json.text ||
    item.json.content ||
    item.json.message ||
    item.json.output ||
    JSON.stringify(item.json, null, 2);

  // Add clear section headers for Agent6
  if (index === 0) {
    finalText +=
      '==============================\n' +
      'NORTH AMERICA SOCIAL MEDIA STRATEGY (Agent4)\n' +
      '==============================\n\n';
  } else if (index === 1) {
    finalText +=
      '\n\n==============================\n' +
      'SOUTHEAST ASIA SOCIAL MEDIA STRATEGY (Agent5)\n' +
      '==============================\n\n';
  } else {
    finalText +=
      '\n\n==============================\n' +
      `ADDITIONAL AGENT OUTPUT ${index + 1}\n` +
      '==============================\n\n';
  }

  finalText += text;
});

// Return ONE single item for downstream Agent6
return [
  {
    json: {
      merged_social_media_strategy: finalText
    }
  }
];
